/* Fictional All-Star voting. Box-score efficiency is a custom metric, not PER/Win Shares. */
let allStarBusy=false,allStarBallotUI={key:'',ids:[],overrides:[]};
function allStarCloseDay(){return Math.max(1,seasonMilestones().start-2)}
function allStarNews(headline,detail='',teams=[]){addNewsItem({category:'All-Star',headline,detail,teams})}
function allStarPerformance(){const map=new Map();for(const g of state.history.filter(g=>g.stage==='Regular season'))for(const row of g.box){if(!(row.mp>0)||!Number.isInteger(row.playerId))continue;let s=map.get(row.playerId);if(!s){s={gp:0,pts:0,reb:0,ast:0,stl:0,blk:0,eff:0};map.set(row.playerId,s)}s.gp++;for(const k of ['pts','reb','ast','stl','blk'])s[k]+=row[k]||0;s.eff+=(row.pts||0)+(row.reb||0)+(row.ast||0)+(row.stl||0)+(row.blk||0)-Math.max(0,(row.fga||0)-(row.fgm||0))-Math.max(0,(row.fta||0)-(row.ftm||0))-(row.tov||0);}return map}
function allStarPopularity(p,t){const random=scheduleRandom(p.id*37+state.year*997),draft=p.bio?.draftPick||60;return Math.max(0,Math.min(100,Math.round(20+random()*35+({Small:0,Medium:10,Large:22}[t.marketSize]||0)+(draft<=3?18:draft<=10?10:0)+(p.ovr>=85?10:0))))}
function allStarVotingStore(){if(state.allStarVoting?.year===state.year)return state.allStarVoting;const random=scheduleRandom(state.year*1559+27),players=state.teams.flatMap(t=>t.roster),cultPool=players.filter(p=>p.ovr<78&&p.ovr>=60),cult= random()<.2&&cultPool.length?cultPool[Math.floor(random()*cultPool.length)].id:null;return state.allStarVoting={year:state.year,phase:'open',lastDay:state.day,entries:state.teams.flatMap(t=>t.roster.map(p=>({id:p.id,popularity:allStarPopularity(p,t),votes:Math.round(state.day*(2000+allStarPopularity(p,t)*80+(p.pts/Math.max(1,p.gp))*450)),campaign:0}))),cult,cultAnnounced:false,events:[],snapshot:[],groups:[],ballot:[],overrides:[],selected:[],teams:[],draftLog:[],game:null,spent:0}}
function allStarSyncEntries(v){for(const t of state.teams)for(const p of t.roster)if(!v.entries.some(e=>e.id===p.id))v.entries.push({id:p.id,popularity:allStarPopularity(p,t),votes:0,campaign:0});const ids=new Set(state.teams.flatMap(t=>t.roster.map(p=>p.id)));v.entries=v.entries.filter(e=>ids.has(e.id))}
function allStarVotingRows(){const v=allStarVotingStore();if(v.phase!=='open')return v.snapshot;const stats=allStarPerformance(),entries=new Map(v.entries.map(e=>[e.id,e]));return state.teams.flatMap(t=>t.roster.map(p=>{const e=entries.get(p.id)||{votes:0,popularity:allStarPopularity(p,t)},s=stats.get(p.id),gp=s?.gp||p.gp||0,ppg=(s?.pts??p.pts)/Math.max(1,gp),rpg=(s?.reb??p.reb)/Math.max(1,gp),apg=(s?.ast??p.ast)/Math.max(1,gp),defense=((s?.stl||0)+(s?.blk||0))/Math.max(1,gp),eff=s?s.eff/s.gp:ppg+rpg+apg,record=t.w+t.l?t.w/(t.w+t.l):.5;return {id:p.id,team:t.id,name:p.name,pos:p.pos,conference:t.conference,ovr:p.ovr,gp,ppg,popularity:e.popularity,fanVotes:e.votes,media:Math.max(0,eff+record*8),peer:Math.max(0,ppg*.25+apg+defense*5),merit:Math.max(0,eff+defense*2+record*4),fanScore:0,mediaScore:0,playerScore:0,score:0}}))}
function allStarGroups(rows){const count=Math.min(leagueRules().allStarPlayers,Math.floor(rows.length/2)),conferences=[...new Set(state.teams.map(t=>t.conference))];if(conferences.length===2&&conferences.every(c=>rows.filter(r=>r.conference===c).length>=count))return conferences.map(name=>({name,count,ids:rows.filter(r=>r.conference===name).map(r=>r.id),starterCount:Math.min(5,count)}));return [{name:'League',count:count*2,ids:rows.map(r=>r.id),starterCount:Math.min(10,count*2)}]}
function allStarScoreRows(rows,groups){for(const group of groups){const pool=rows.filter(r=>group.ids.includes(r.id));for(const [raw,key] of [['fanVotes','fanScore'],['media','mediaScore'],['peer','playerScore']]){const max=Math.max(1,...pool.map(r=>r[raw]));for(const r of pool)r[key]=100*r[raw]/max;}for(const r of pool)r.score=.5*r.fanScore+.25*r.mediaScore+.25*r.playerScore;}return rows}
function allStarStarters(v,group,overrides=[]){const pool=v.snapshot.filter(r=>group.ids.includes(r.id)).sort((a,b)=>b.score-a.score||b.merit-a.merit||a.id-b.id),locked=leagueRules().allStarSelection==='locked',guards=group.starterCount===10?4:2,selected=locked?[...pool.filter(r=>['PG','SG'].includes(r.pos)).slice(0,guards),...pool.filter(r=>!['PG','SG'].includes(r.pos)).slice(0,group.starterCount-guards)]:pool.slice(0,group.starterCount);for(const r of pool)if(selected.length<group.starterCount&&!selected.some(x=>x.id===r.id))selected.push(r);
 const cult=pool.find(r=>r.id===v.cult);if(cult&&!overrides.includes(cult.id)&&cult.fanVotes>=Math.max(...pool.map(r=>r.fanVotes))&&!selected.some(r=>r.id===cult.id)){const replace=selected.filter(r=>!locked||['PG','SG'].includes(r.pos)===['PG','SG'].includes(cult.pos)).sort((a,b)=>a.score-b.score)[0];if(replace)selected[selected.indexOf(replace)]=cult;}
 return selected;
}
function allStarBallotContext(v=allStarVotingStore(),overrides=allStarBallotUI.overrides){const group=v.groups.find(g=>g.ids.some(id=>v.snapshot.some(r=>r.id===id&&r.conference===team().conference)))||v.groups[0];if(!group)return {rows:[],quota:0,group:null};const starters=allStarStarters(v,group,overrides),rows=v.snapshot.filter(r=>group.ids.includes(r.id)&&r.team!==controlledTeamId()&&!starters.some(s=>s.id===r.id)).sort((a,b)=>b.merit-a.merit||a.id-b.id);return {rows,quota:Math.min(group.count-group.starterCount,rows.length),group}}
function allStarPrepareBallotUI(v){const key=activeSaveId+':'+v.year;if(allStarBallotUI.key!==key)allStarBallotUI={key,ids:[],overrides:[]}}
function allStarToggleBallot(id){const v=allStarVotingStore();if(v.phase!=='review'||allStarBusy)return;allStarPrepareBallotUI(v);const {rows,quota}=allStarBallotContext(v);if(!rows.some(r=>r.id===id))return;if(allStarBallotUI.ids.includes(id))allStarBallotUI.ids=allStarBallotUI.ids.filter(x=>x!==id);else if(allStarBallotUI.ids.length<quota)allStarBallotUI.ids.push(id);else toast('Choose '+quota+' reserves.');showAllStarWeekend()}
function allStarToggleOverride(){const v=allStarVotingStore();if(v.phase!=='review'||v.cult===null||allStarBusy)return;allStarPrepareBallotUI(v);allStarBallotUI.overrides=allStarBallotUI.overrides.length?[]:[v.cult];allStarBallotUI.ids=[];showAllStarWeekend()}
function allStarTick(){if(!leagueRules().allStarEnabled||state.allStarReport?.length)return;const v=allStarVotingStore();if(v.phase!=='open')return;allStarSyncEntries(v);const rows=allStarVotingRows(),byId=new Map(rows.map(r=>[r.id,r]));for(let day=v.lastDay+1;day<=Math.min(state.day,allStarCloseDay());day++){const random=scheduleRandom(state.year*7757+day*97);for(const e of v.entries){const r=byId.get(e.id);if(!r)continue;e.votes+=Math.round((2000+r.ppg*450+e.popularity*80)*(e.id===v.cult?12:1));}if(v.entries.length&&day%5===0){const e=v.entries[Math.floor(random()*v.entries.length)],r=byId.get(e.id),positive=random()<.65,delta=positive?5000:-12000;e.votes=Math.max(0,e.votes+delta);const text=r.name+(positive?' went viral for a charity appearance (+5,000 fan votes).':' complained about minutes on social media (−12,000 fan votes).');v.events.push(text);v.events=v.events.slice(-40);allStarNews('All-Star voting: '+text,'',[r.team]);}}
 v.lastDay=Math.min(state.day,allStarCloseDay());
 if(v.cult!==null&&!v.cultAnnounced&&state.day>0){v.cultAnnounced=true;const r=byId.get(v.cult);if(r){const text=r.name+' has attracted a devoted fan campaign. A fan-favorite starter may be reviewed before selections are confirmed.';v.events.push(text);allStarNews('All-Star fan campaign gathers momentum',text,[r.team]);}}
 if(state.day>=allStarCloseDay()){let eligible=allStarVotingRows().filter(r=>r.gp>0);if(eligible.length<2)eligible=allStarVotingRows();v.groups=allStarGroups(eligible);v.snapshot=allStarScoreRows(eligible,v.groups);v.phase='review';allStarBallotUI={key:'',ids:[],overrides:[]};addGMMessage('All-Star','League office','All-Star reserves ballot is ready','Fan, media and player voting has closed. Submit your conference reserves ballot, excluding your own players, or abstain. Review any fan-favorite starter before confirming selections.');allStarNews('All-Star voting closes: coaches ballots open','Review the All-Star Weekend ballot in Schedule.');}
}
function allStarSimulationPaused(){return leagueRules().allStarEnabled&&state.allStarVoting?.year===state.year&&state.allStarVoting.phase==='review'}
async function allStarCampaign(id){if(allStarBusy||!ownerCanManage()||!leagueRules().allStarEnabled)return;const v=allStarVotingStore(),p=team().roster.find(p=>p.id===id),e=v.entries.find(e=>e.id===id);if(v.phase!=='open'||state.day>=allStarCloseDay()||!p||!e)return toast('Voting is closed or this player is unavailable.');if(!leagueRules().budgetEnabled)return toast('Campaigns require team budgets to be enabled.');if(e.campaign||v.spent>=1)return toast('One campaign per player and a $1M team limit per season.');const f=financeFor();if(f.cash<.25)return toast('A campaign requires $250,000 in available cash.');const before=snapshotState();allStarBusy=true;try{financePost(f,'operations',.25,true);financeSync(team());e.campaign=15000;e.votes+=15000;v.spent+=.25;allStarNews('All-Star campaign: '+p.name,team().city+' invests $250,000 in a campaign, adding 15,000 fan votes.',[0]);if(await save()===false){state=before;toast('Campaign could not be saved. No money was spent.')}}catch(e){state=before;toast('Campaign could not be saved. No money was spent.')}finally{allStarBusy=false;render();showAllStarWeekend()}}
function allStarSelect(v,ballot,overrides){const selected=[];for(const group of v.groups){const starters=allStarStarters(v,group,overrides),candidates=v.snapshot.filter(r=>group.ids.includes(r.id)&&!starters.some(s=>s.id===r.id)),seats=group.count-starters.length,votes=new Map(candidates.map(r=>[r.id,0]));for(const club of state.teams){if(club.id===controlledTeamId()||group.name!=='League'&&club.conference!==group.name)continue;const random=scheduleRandom(state.year*333+club.id*701);const order=candidates.filter(r=>r.team!==club.id).map(r=>({r,score:r.merit+random()*6})).sort((a,b)=>b.score-a.score);for(const x of order.slice(0,seats))votes.set(x.r.id,votes.get(x.r.id)+1);}for(const id of ballot)if(votes.has(id))votes.set(id,votes.get(id)+1);const reserves=candidates.sort((a,b)=>votes.get(b.id)-votes.get(a.id)||b.merit-a.merit||a.id-b.id).slice(0,seats);selected.push(...starters.map(r=>({...r,role:'Starter',group:group.name})),...reserves.map(r=>({...r,role:'Reserve',group:group.name})));}return selected}
function allStarAssign(v){const pool=[...v.selected].sort((a,b)=>b.fanVotes-a.fanVotes||b.score-a.score||a.id-b.id),n=Math.floor(pool.length/2);v.draftLog=[];if(leagueRules().allStarAssignment==='conference'&&v.groups.length===2){v.teams=v.groups.map(g=>({name:g.name,ids:v.selected.filter(r=>r.group===g.name).map(r=>r.id)}));return;}if(leagueRules().allStarAssignment==='draft'&&pool.length>=2){const left={name:'Team '+pool[0].name,ids:[pool[0].id]},right={name:'Team '+pool[1].name,ids:[pool[1].id]},teams=[left,right];v.draftLog.push(pool[0].name+' and '+pool[1].name+' lead fan voting and become captains.');const remaining=pool.slice(2).sort((a,b)=>b.merit-a.merit||b.score-a.score);for(let i=0;i<remaining.length;i++){let side=i%4===0||i%4===3?1:0;if(teams[side].ids.length>=n)side=1-side;teams[side].ids.push(remaining[i].id);v.draftLog.push(teams[side].name+' selects '+remaining[i].name+'.');}v.teams=teams;return;}const random=scheduleRandom(state.year*931);for(let i=pool.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}v.teams=[{name:'Team Gold',ids:pool.slice(0,n).map(r=>r.id)},{name:'Team Orange',ids:pool.slice(n,n*2).map(r=>r.id)}];}
async function confirmAllStarSelections(abstain=false,{quiet=false}={}){if(allStarBusy||!(abstain?gmCanAdvance():ownerCanManage()))return;const v=allStarVotingStore();if(v.phase!=='review')return;allStarPrepareBallotUI(v);const context=allStarBallotContext(v),ballot=abstain?[]:allStarBallotUI.ids;if(!abstain&&(ballot.length!==context.quota||new Set(ballot).size!==ballot.length||ballot.some(id=>!context.rows.some(r=>r.id===id))))return toast('Select exactly '+context.quota+' eligible reserves, excluding your own players.');const before=snapshotState();allStarBusy=true;try{v.ballotTeamId=controlledTeamId();v.ballot=[...ballot];v.overrides=[...allStarBallotUI.overrides];v.selected=allStarSelect(v,v.ballot,v.overrides);allStarAssign(v);v.phase='final';for(const group of v.groups)for(const role of ['Starter','Reserve']){const rows=v.selected.filter(r=>r.group===group.name&&r.role===role);for(let i=0;i<rows.length;i+=5)allStarNews('All-Star selections: '+group.name+' '+role.toLowerCase()+'s',rows.slice(i,i+5).map(r=>r.name+' ('+state.teams[r.team].abbr+')').join(', '),[...new Set(rows.slice(i,i+5).map(r=>r.team))]);}
 for(const group of v.groups){const merit=v.snapshot.filter(r=>group.ids.includes(r.id)).sort((a,b)=>b.merit-a.merit).slice(0,group.count);for(const r of merit.filter(r=>!v.selected.some(s=>s.id===r.id))){const p=state.teams.flatMap(t=>t.roster).find(p=>p.id===r.id);if(!p)continue;p.moraleAdjustment=Math.max(-100,(p.moraleAdjustment||0)-6);allStarNews('All-Star snub: '+p.name+' voices disappointment','A strong first half did not earn a selection. Morale drops by 6.',[r.team]);}}
 for(const line of v.draftLog)allStarNews('All-Star captains draft',line);if(state.day>=seasonMilestones().end&&!state.allStarReport?.length){state.allStarReport=allStarReport();state.allStarReport.filter(s=>/^(Three-point contest:|Dunk contest:|Skills challenge:|All-Star Game:|Showcase MVP:)/.test(s)).forEach(say);}if(await save()===false){state=before;toast('Selections could not be saved. Please try again.')}}catch(e){state=before;simulationFailure(e);toast('Selections could not be saved. Please try again.')}finally{allStarBusy=false;if(!quiet){render();showAllStarWeekend()}}}
function simulateAllStarExhibition(v,options={}){if(v.game)return v.game;const random=scheduleRandom(state.year*827+(options.seed||65)),scores=[0,0],events=[],box=new Map(v.selected.map(r=>[r.id,0])),elam=options.elam??!!leagueRules().allStarElam;let possession=0;const play=(quarter,clock,target=null)=>{const side=possession++%2,ids=v.teams[side].ids;if(!ids.length)return;const id=ids[Math.floor(random()*ids.length)],r=v.selected.find(r=>r.id===id),three=random()<.35,made=random()<.5+(r.ovr-75)*.003,points=made?(three?3:2):0;if(points){scores[side]+=points;box.set(id,box.get(id)+points)}events.push((quarter==='OT'?'OT':'Q'+quarter)+' '+clock+' · '+r.name+(made?' makes a '+(three?'three-pointer':'basket'):' misses a '+(three?'three-pointer':'jumper'))+' · '+scores.join('–')+(target?' · Target '+target:''));};for(let q=1;q<=3;q++)for(let i=0;i<40;i++){const sec=Math.max(0,720-(i+1)*18);play(q,Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0'));}const target=elam?Math.max(...scores)+24:null;if(elam){let safety=0;while(Math.max(...scores)<target&&safety++<200)play(4,'UNTIMED',target);if(Math.max(...scores)<target){const side=scores[0]>=scores[1]?0:1,points=target-scores[side];scores[side]=target;box.set(v.teams[side].ids[0],box.get(v.teams[side].ids[0])+points);events.push('Q4 UNTIMED · '+v.teams[side].name+' reaches the target after the extended exhibition sequence.');}}else{for(let i=0;i<40;i++){const sec=Math.max(0,720-(i+1)*18);play(4,Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0'));}let overtime=0;while(scores[0]===scores[1]&&overtime++<20){play('OT','0:20');play('OT','0:00');}if(scores[0]===scores[1]){scores[0]++;box.set(v.teams[0].ids[0],box.get(v.teams[0].ids[0])+1);events.push('Overtime · Deciding free throw: '+scores.join('–'));}}
 const winner=scores[0]>scores[1]?0:1,mvp=[...v.teams[winner].ids].sort((a,b)=>box.get(b)-box.get(a))[0];return v.game={scores,target,events,box:[...box].map(([id,pts])=>({id,pts})),mvp}}
const allStarTeamsBeforeVoting=allStarTeams;allStarTeams=function(top,random){const v=state.allStarVoting;if(v?.year===state.year&&v.phase==='final'&&v.teams.length===2){const byId=new Map(top.map(r=>[r.p.id,r])),resolve=ids=>ids.map(id=>byId.get(id)||{p:v.selected.find(r=>r.id===id),t:state.teams[v.selected.find(r=>r.id===id).team]});return {left:resolve(v.teams[0].ids),right:resolve(v.teams[1].ids),names:v.teams.map(t=>t.name),mode:'Fan / media / player voting · Coaches reserves'}}return allStarTeamsBeforeVoting(top,random)};
const allStarReportBeforeVoting=allStarReport;allStarReport=function(){const report=allStarReportBeforeVoting(),v=state.allStarVoting;if(v?.year!==state.year||v.phase!=='final'||!v.selected.length)return report;const g=simulateAllStarExhibition(v);return report.map(line=>line.startsWith('All-Star Game:')?'All-Star Game: '+v.teams[0].name+' '+g.scores[0]+' — '+v.teams[1].name+' '+g.scores[1]+(g.target?'. Untimed fourth quarter; target '+g.target:'')+'. Exhibition only.':line.startsWith('Showcase MVP:')?'Showcase MVP: '+v.selected.find(r=>r.id===g.mvp).name+'.':line)};
const allStarMilestoneBeforeVoting=seasonMilestoneDay;seasonMilestoneDay=function(){allStarTick();if(!allStarSimulationPaused())return allStarMilestoneBeforeVoting()};
const showAllStarBeforeVoting=showAllStarWeekend;
showAllStarWeekend=function(){if(!leagueRules().allStarEnabled||state.allStarReport?.length&&state.allStarVoting?.year!==state.year)return showAllStarBeforeVoting();const v=allStarVotingStore();if(v.phase==='open'){allStarSyncEntries(v);if(state.day>=allStarCloseDay()){allStarTick();save();}}allStarPrepareBallotUI(v);const rows=allStarScoreRows(allStarVotingRows().map(r=>({...r})),v.phase==='open'?allStarGroups(allStarVotingRows()):v.groups).sort((a,b)=>b.score-a.score||a.id-b.id),ctx=allStarBallotContext(v),cult=v.snapshot.find(r=>r.id===v.cult),hasCult=cult&&v.groups.some(g=>allStarStarters(v,g).some(r=>r.id===cult.id));
 const campaigns=v.phase==='open'?`<details><summary>Your marketing campaigns · ${money(v.spent)} / $1.0M spent</summary><p>$250,000 adds 15,000 fan votes. One campaign per player. Team budgets must be enabled.</p>${team().roster.map(p=>{const e=v.entries.find(e=>e.id===p.id);return `<p>${escapeHTML(p.name)} <button onclick="allStarCampaign(${p.id})" ${allStarBusy||e?.campaign||v.spent>=1||!leagueRules().budgetEnabled||state.day>=allStarCloseDay()?'disabled':''}>${e?.campaign?'Campaign complete':'Campaign · $250,000'}</button></p>`}).join('')}</details>`:'';
 const ballot=v.phase==='review'?`<section class="panel note"><h3>Coaches’ reserves ballot · ${escapeHTML(ctx.group?.name||'League')}</h3><p>Choose ${ctx.quota} reserves (${allStarBallotUI.ids.length} selected). You cannot vote for your own players. Your ballot joins the other coaches’ votes; it does not guarantee selection.</p>${hasCult?`<div class="note"><strong>Fan-favorite review: ${escapeHTML(cult.name)}</strong><p>${cult.ovr} OVR · ${cult.fanVotes.toLocaleString()} fan votes. Keep the fan choice or restore the weighted-vote starter.</p><button onclick="allStarToggleOverride()">${allStarBallotUI.overrides.length?'Restore fan choice':'Override fan choice'}</button></div>`:''}<div style="max-height:340px;overflow:auto">${ctx.rows.map(r=>`<label style="display:flex;align-items:center;gap:10px;padding:10px"><input type="checkbox" ${allStarBallotUI.ids.includes(r.id)?'checked':''} onchange="allStarToggleBallot(${r.id})"><span>${escapeHTML(r.name)} · ${escapeHTML(state.teams[r.team].abbr)} · ${r.pos} · ${r.ppg.toFixed(1)} PPG</span></label>`).join('')}</div><div class="actions"><button class="primary" onclick="confirmAllStarSelections(false)" ${allStarBusy||allStarBallotUI.ids.length!==ctx.quota?'disabled':''}>Submit ballot & announce selections</button><button onclick="confirmAllStarSelections(true)" ${allStarBusy?'disabled':''}>Abstain & announce selections</button></div><p>Simulation resumes after selections are confirmed.</p></section>`:'';
 const selections=v.phase==='final'?`<section><h3>Confirmed All-Stars</h3>${v.groups.map(g=>`<h4>${escapeHTML(g.name)}</h4>${v.selected.filter(r=>r.group===g.name).map(r=>`<p>${escapeHTML(r.name)} · ${escapeHTML(state.teams[r.team].abbr)} · ${r.role}</p>`).join('')}`).join('')}${v.draftLog.length?'<details><summary>Captains draft</summary>'+v.draftLog.map(s=>'<p>'+escapeHTML(s)+'</p>').join('')+'</details>':''}</section>`:'';
 titleModal('All-Star voting & weekend',`<p>Voting closes ${scheduleDateLabel(allStarCloseDay(),true)} · ${v.phase==='open'?'Voting open':v.phase==='review'?'Awaiting your ballot':'Selections announced'}</p><p>50% fan vote · 25% media · 25% player vote. Media scores use box-score efficiency and team record; player scores reward production, playmaking and defense. ${leagueRules().allStarSelection==='locked'?'Starters: two guards and three frontcourt players per team when available.':'Positionless selection.'}</p>${allStarEventsMarkup()}${campaigns}${ballot}${selections}<details ${v.phase==='open'?'open':''}><summary>Voting leaderboard</summary><div class="tablewrap" style="max-height:440px;overflow:auto"><table><thead><tr><th>Player</th><th>Team</th><th>Hype</th><th>Fan votes</th><th>Fan score</th><th>Media</th><th>Players</th><th>Weighted</th></tr></thead><tbody>${rows.slice(0,100).map(r=>`<tr><td>${escapeHTML(r.name)}</td><td>${escapeHTML(state.teams[r.team].abbr)}</td><td>${r.popularity}</td><td>${r.fanVotes.toLocaleString()}</td><td>${r.fanScore.toFixed(1)}</td><td>${r.mediaScore.toFixed(1)}</td><td>${r.playerScore.toFixed(1)}</td><td>${r.score.toFixed(1)}</td></tr>`).join('')}</tbody></table></div><p>Top 100 shown. Component scores are normalized within the selection pool.</p></details>${v.events.length?'<details><summary>Fan voting stories</summary>'+v.events.map(s=>'<p>'+escapeHTML(s)+'</p>').join('')+'</details>':''}${state.allStarReport?.length?'<h3>Weekend results</h3>'+state.allStarReport.map(s=>'<p>'+escapeHTML(s)+'</p>').join(''):'<p>Exhibition results will appear after the final day of All-Star Weekend.</p>'}${v.game?'<details><summary>All-Star Game play-by-play'+(v.game.target?' · Target '+v.game.target:'')+'</summary><ol style="max-height:420px;overflow:auto">'+v.game.events.map(s=>'<li>'+escapeHTML(s)+'</li>').join('')+'</ol></details>':''}<button onclick="closeTitleModal()">Close</button>`)
};
function readAllStarVoting(raw,bad,count,year){if(raw===undefined)return undefined;const int=(n,l,h)=>Number.isInteger(n)&&n>=l&&n<=h,num=(n,l,h)=>Number.isFinite(n)&&n>=l&&n<=h,str=(s,max)=>typeof s==='string'&&s.length<=max,id=n=>int(n,0,10000000),ids=(a,max)=>Array.isArray(a)&&a.length<=max&&a.every(id)&&new Set(a).size===a.length,strings=(a,max)=>Array.isArray(a)&&a.length<=max&&a.every(s=>str(s,600));if(!raw||raw.year!==year||!['open','review','final'].includes(raw.phase)||!int(raw.lastDay,0,367)||!num(raw.spent,0,1)||!int(raw.spent*4,0,4)||raw.cult!==null&&!id(raw.cult)||typeof raw.cultAnnounced!=='boolean'||!Array.isArray(raw.entries)||raw.entries.length>1080||!strings(raw.events,40)||!Array.isArray(raw.snapshot)||raw.snapshot.length>1080||!Array.isArray(raw.groups)||raw.groups.length>2||!ids(raw.ballot,60)||!ids(raw.overrides,1)||!Array.isArray(raw.selected)||raw.selected.length>60||!Array.isArray(raw.teams)||raw.teams.length>2||!strings(raw.draftLog,60))bad('invalid All-Star voting');if(raw.ballotTeamId!==undefined&&!int(raw.ballotTeamId,-1,count-1))bad('invalid All-Star ballot franchise');
 const seen=new Set(),entries=raw.entries.map(e=>{if(!e||!id(e.id)||seen.has(e.id)||!int(e.popularity,0,100)||!int(e.votes,0,1000000000)||![0,15000].includes(e.campaign))bad('invalid All-Star votes');seen.add(e.id);return {id:e.id,popularity:e.popularity,votes:e.votes,campaign:e.campaign}});
 const readRow=r=>{if(!r||!id(r.id)||!int(r.team,0,count-1)||!str(r.name,80)||!['PG','SG','SF','PF','C'].includes(r.pos)||!str(r.conference,35)||!int(r.ovr,1,99)||!int(r.gp,0,10000000)||!num(r.ppg,0,500)||!int(r.popularity,0,100)||!int(r.fanVotes,0,1000000000)||!['media','peer','merit'].every(k=>num(r[k],0,2000))||!['fanScore','mediaScore','playerScore','score'].every(k=>num(r[k],0,100.00001)))bad('invalid All-Star candidate');return Object.fromEntries(['id','team','name','pos','conference','ovr','gp','ppg','popularity','fanVotes','media','peer','merit','fanScore','mediaScore','playerScore','score'].map(k=>[k,r[k]]))};
 const snapshot=raw.snapshot.map(readRow),snapshotIds=new Set(snapshot.map(r=>r.id));if(snapshotIds.size!==snapshot.length)bad('duplicate All-Star candidate');const groups=raw.groups.map(g=>{if(!g||!str(g.name,35)||!int(g.count,0,60)||!int(g.starterCount,0,10)||g.starterCount>g.count||!ids(g.ids,1080)||g.ids.some(id=>!snapshotIds.has(id))||g.count>g.ids.length)bad('invalid All-Star pool');return {name:g.name,count:g.count,starterCount:g.starterCount,ids:[...g.ids]}});if(new Set(groups.flatMap(g=>g.ids)).size!==groups.reduce((n,g)=>n+g.ids.length,0))bad('overlapping All-Star pools');
 const selected=raw.selected.map(r=>{const row=readRow(r);if(!snapshotIds.has(r.id)||!['Starter','Reserve'].includes(r.role)||!groups.some(g=>g.name===r.group&&g.ids.includes(r.id)))bad('invalid All-Star selection');return {...row,role:r.role,group:r.group}}),selectedIds=new Set(selected.map(r=>r.id));if(selectedIds.size!==selected.length||raw.ballot.some(id=>!snapshotIds.has(id)||snapshot.find(r=>r.id===id).team===(raw.ballotTeamId??0))||raw.overrides.some(id=>id!==raw.cult))bad('invalid All-Star ballot');
 const teams=raw.teams.map(t=>{if(!t||!str(t.name,100)||!ids(t.ids,30)||t.ids.some(id=>!selectedIds.has(id)))bad('invalid All-Star team');return {name:t.name,ids:[...t.ids]}});if(raw.phase==='final'&&(teams.length!==2||teams[0].ids.length!==teams[1].ids.length||new Set(teams.flatMap(t=>t.ids)).size!==selected.length||teams.flatMap(t=>t.ids).length!==selected.length||groups.some(g=>selected.filter(r=>r.group===g.name).length!==g.count)))bad('invalid finalized All-Stars');
 let game=null;if(raw.game){const g=raw.game;if(raw.phase!=='final'||!Array.isArray(g.scores)||g.scores.length!==2||!g.scores.every(s=>int(s,0,1000))||g.scores[0]===g.scores[1]||g.target!==null&&!int(g.target,24,1000)||!strings(g.events,360)||!Array.isArray(g.box)||g.box.length!==selected.length||!selectedIds.has(g.mvp))bad('invalid All-Star exhibition');const box=g.box.map(r=>{if(!r||!selectedIds.has(r.id)||!int(r.pts,0,1000))bad('invalid All-Star box score');return {id:r.id,pts:r.pts}});if(new Set(box.map(r=>r.id)).size!==box.length||teams.some((t,i)=>box.filter(r=>t.ids.includes(r.id)).reduce((n,r)=>n+r.pts,0)!==g.scores[i])||g.target!==null&&Math.max(...g.scores)<g.target)bad('invalid All-Star scoring');game={scores:[...g.scores],target:g.target,events:[...g.events],box,mvp:g.mvp};}
 return {ballotTeamId:raw.ballotTeamId??0,year:raw.year,phase:raw.phase,lastDay:raw.lastDay,entries,cult:raw.cult,cultAnnounced:raw.cultAnnounced,events:[...raw.events],snapshot,groups,ballot:[...raw.ballot],overrides:[...raw.overrides],selected,teams,draftLog:[...raw.draftLog],game,spent:raw.spent};
}
